import { writeFile, mkdir } from "fs/promises";
import { existsSync } from "fs";
import path from "path";

interface SaveRequest {
  title: string;
  text: string;
  excerpt: string;
  url: string;
  siteName: string;
  publishedDate: string | null;
  readingTime: number;
  tags: string[];
  vaultPath: string;
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .substring(0, 100);
}

function formatDate(date: string | null): string {
  if (!date) return new Date().toISOString().split("T")[0];
  try {
    return new Date(date).toISOString().split("T")[0];
  } catch {
    return new Date().toISOString().split("T")[0];
  }
}

function generateMarkdown(data: SaveRequest): string {
  const { title, text, excerpt, url, siteName, publishedDate, readingTime, tags } = data;
  const dateStr = formatDate(publishedDate);
  const tagsStr = tags.length > 0 ? `\n${tags.map(t => ` #${t.replace(/\s+/g, "-")}`).join("")}` : "";

  return `# ${title}

> ${excerpt}

**Source:** [${siteName}](${url})  
**Date:** ${dateStr}  
**Reading time:** ${readingTime} min${tagsStr}

---

${text}

---

*Saved with Smart Clipper*
`;
}

export async function POST(request: NextRequest) {
  try {
    const data: SaveRequest = await request.json();

    const { title, text, url, vaultPath, tags } = data;

    if (!title || !text || !url || !vaultPath) {
      return NextResponse.json(
        { error: "Missing required fields: title, text, url, vaultPath" },
        { status: 400 }
      );
    }

    // Security: Ensure vaultPath is a valid directory path (prevent path traversal)
    const vaultDir = path.resolve(vaultPath);
    if (!existsSync(vaultDir)) {
      // Try to create the directory
      try {
        await mkdir(vaultDir, { recursive: true });
      } catch {
        return NextResponse.json(
          { error: "Vault path does not exist and could not be created" },
          { status: 400 }
        );
      }
    }

    // Generate filename
    const dateStr = formatDate(data.publishedDate);
    const baseName = `${dateStr}-${slugify(title)}`;
    let fileName = `${baseName}.md`;
    let filePath = path.join(vaultDir, fileName);

    // Handle duplicate filenames
    let counter = 1;
    while (existsSync(filePath)) {
      fileName = `${baseName}-${counter}.md`;
      filePath = path.join(vaultDir, fileName);
      counter++;
    }

    // Generate and write markdown
    const markdown = generateMarkdown(data);
    await writeFile(filePath, markdown, "utf-8");

    return NextResponse.json({
      success: true,
      filePath,
      fileName,
      message: `Saved to ${fileName}`
    });
  } catch (error) {
    console.error("Save error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to save" },
      { status: 500 }
    );
  }
}
